// Unit self-check bench for pe4_fmul / pe4_act / pe4_quant / sigmoid ROM.
// Vectors: +VECTORS=<dir>/math.txt (generated by model/vectors.py).
`timescale 1ns/1ps
module tb_math_v4;
    logic clk = 0, rst_n = 0;
    always #5 clk = ~clk;
    integer fd, errors = 0, checked = 0, i, rc;
    logic [8*8-1:0] tag;
    logic [1023:0] a1, a2, a3, a4;
    logic [1023:0] line;
    string vecdir, path;
    logic fm_v = 0;
    logic [31:0] fm_a, fm_b, fm_r;
    logic fm_ov;
    pe4_fmul fmul_dut (.clk(clk), .rst_n(rst_n), .in_valid(fm_v),
        .a(fm_a), .b(fm_b), .out_valid(fm_ov), .result(fm_r));
    logic ac_v = 0;
    logic [31:0] ac_g [0:3], ac_u [0:3], ac_w [0:3];
    logic [15:0] ac_gb = 16'h0000, ac_ub = 16'h0000;
    logic [15:0] ac_h [0:3];
    logic ac_ov;
    pe4_act act_dut (.clk(clk), .rst_n(rst_n), .in_valid(ac_v),
        .g(ac_g), .u(ac_u), .w(ac_w), .gb(ac_gb), .ub(ac_ub),
        .out_valid(ac_ov), .h(ac_h));
    logic qu_v = 0;
    logic [511:0] qu_h;
    logic qu_ov;
    logic [255:0] qu_q;
    logic [7:0] qu_se;
    logic [10:0] qu_otag;
    logic qu_err;
    pe4_quant quant_dut (.clk(clk), .rst_n(rst_n), .in_valid(qu_v),
        .in_h(qu_h), .in_tag(11'd0), .out_valid(qu_ov), .out_q(qu_q),
        .out_se(qu_se), .out_tag(qu_otag), .err_nonfinite(qu_err));
    logic [15:0] sg_code = 0;
    logic [31:0] sg_val;
    pe4_sigmoid_rom sig_rom (.clk(clk), .code(sg_code), .value(sg_val));
    logic [31:0] exp_fm [0:8191];
    logic [15:0] exp_ac [0:8191];
    logic [255:0] exp_qu [0:1023];
    logic [7:0] exp_qu_se [0:1023];
    integer fm_head = 0, fm_tail = 0;
    integer ac_head = 0, ac_tail = 0;
    integer qu_head = 0, qu_tail = 0;
    task harvest();
        begin
            if (fm_ov) begin
                if (fm_r !== exp_fm[fm_tail]) begin
                    $display("FM mismatch got=%08x want=%08x",
                             fm_r, exp_fm[fm_tail]);
                    errors++;
                end
                fm_tail = (fm_tail + 1) % 8192;
                checked++;
            end
            if (ac_ov) begin
                for (i = 0; i < 4; i++)
                    if (ac_h[i] !== exp_ac[(ac_tail*4 + i) % 32768]) begin
                        $display("AC mismatch lane%0d got=%04x want=%04x", i,
                                 ac_h[i], exp_ac[(ac_tail*4 + i) % 32768]);
                        errors++;
                    end
                ac_tail = (ac_tail + 1) % 8192;
                checked++;
            end
            if (qu_ov) begin
                if (qu_q !== exp_qu[qu_tail] || qu_se !== exp_qu_se[qu_tail]) begin
                    $display("QU mismatch se=%02x/%02x", qu_se,
                             exp_qu_se[qu_tail]);
                    errors++;
                end
                qu_tail = (qu_tail + 1) % 1024;
                checked++;
            end
        end
    endtask
    initial begin
        if (!$value$plusargs("VECTORS=%s", vecdir)) vecdir = "vectors";
        path = {vecdir, "/math.txt"};
        fd = $fopen(path, "r");
        if (fd == 0) begin
            $display("FATAL cannot open %s", path);
            $finish;
        end
        repeat (4) @(posedge clk);
        rst_n = 1;
        @(posedge clk);
        // R4-024: line-based parsing — fscanf with a fixed 5-column format
        // would pull tokens from the NEXT line for FM(4)/QU(4)/SG(3) rows
        rc = $fgets(line, fd);
        while (rc != 0) begin
            rc = $sscanf(line, "%s %h %h %h %h", tag, a1, a2, a3, a4);
            fm_v = 0; ac_v = 0; qu_v = 0;
            if (tag == "FM" && rc >= 4) begin
                fm_a = 32'(a1); fm_b = 32'(a2);
                exp_fm[fm_head] = 32'(a3);
                fm_head = (fm_head + 1) % 8192;
                fm_v = 1;
            end else if (tag == "AC" && rc >= 5) begin
                for (i = 0; i < 4; i++) begin
                    ac_g[i] = a1[32*i +: 32];
                    ac_u[i] = a2[32*i +: 32];
                    ac_w[i] = a3[32*i +: 32];
                    exp_ac[(ac_head*4 + i) % 32768] = a4[16*i +: 16];
                end
                ac_head = (ac_head + 1) % 8192;
                ac_v = 1;
            end else if (tag == "QU" && rc >= 4) begin
                qu_h = 512'(a1);
                exp_qu[qu_head] = 256'(a2);
                exp_qu_se[qu_head] = 8'(a3);
                qu_head = (qu_head + 1) % 1024;
                qu_v = 1;
            end else if (tag == "SG" && rc >= 3) begin
                sg_code = 16'(a1);
                @(posedge clk);
                @(posedge clk);
                if (sg_val !== 32'(a2)) begin
                    $display("SG mismatch code=%04x got=%08x want=%08x",
                             sg_code, sg_val, 32'(a2));
                    errors++;
                end
                checked++;
            end
            @(posedge clk);
            // R4-fix: one-cycle in_valid strobe. Clearing only at the next
            // line's parse left the strobes high for TWO cycles, so every
            // vector entered the DUT twice and drained the scoreboards.
            fm_v = 0; ac_v = 0; qu_v = 0;
            harvest();
            @(posedge clk);
            harvest();
            rc = $fgets(line, fd);
        end
        $fclose(fd);
        repeat (80) begin @(posedge clk); harvest(); end
        if (errors == 0 && checked > 0)
            $display("PASS math checked=%0d", checked);
        else
            $display("FAIL math errors=%0d checked=%0d", errors, checked);
        $finish;
    end
endmodule
